    class TestSpec {
        <<Test File>>
        +execute()
    }

    class LoginPage {
        <<Page Object>>
        -emailInput: Locator
        -passwordInput: Locator
        -signInButton: Locator
        +login(email, password)
    }

    class PlaywrightDOM {
        <<Browser>>
        +getByLabel()
        +getByRole()
    }

    TestSpec ..> LoginPage : Instantiates & calls login()
    LoginPage --> PlaywrightDOM : Encapsulates DOM interaction

